def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    opp_d = 0
    for a, b in history:
        if b == 'D':
            opp_d += 1

    if n == 1:
        return 'D' if opp_d > 0 else 'C'

    # Last round: always defect
    if n >= 99:
        return 'D'

    # Endgame: punish defection in the last 10 rounds
    if n >= 90 and history[-1][1] == 'D':
        return 'D'

    # Exploit pure cooperators: if opponent has never defected, defect
    if opp_d == 0:
        return 'D'

    # If opponent defects frequently, defect
    if opp_d * 2 >= n:
        return 'D'

    # Otherwise, cooperate to maintain mutual cooperation
    return 'C'
